// Minimal sketch: enqueue/dequeue with per-tenant credits (pseudo-C)
class TenantQueue {
  constructor(creditLimit) {
    this.credits = creditLimit;
    this.queue = [];
  }
  enqueue(req) { this.queue.push(req); }
  dequeue() { return this.queue.shift(); }
}
function chooseNext(tenants) {
  // pick queue with max deficit ratio: (creditUsed / max(credit,1))
  let best = null; let bestScore = -Infinity;
  for (const t of tenants) {
    const score = t.credits <= 0 ? -Infinity : 1 - t.credits / t.creditLimit;
    if (score > bestScore) { bestScore = score; best = t; }
  }
  return best && best.queue.length ? best.dequeue() : null;
}
```

